const host=(ctx,path,label,key,icon)=>{const nav={group:'Коммерция',path:'/admin/'+path,label,permission:'orders.view',icon};const Comp=ctx.admin?.resolveHostPage?.(key);const page={path,label,group:'Коммерция',permission:'orders.view',hostPageKey:key,...(Comp?{Component:Comp}:{})};if(ctx.admin?.registerNavItem){ctx.admin.registerNavItem(nav);ctx.admin.registerPage?.(page)}else{ctx.registerAdminNavItem?.(nav);ctx.registerAdminRoute?.(page)}};export const JaseflyFrontendModule={slug:'orders',version:'1.0.0',sdkVersion:1,async register(ctx){host(ctx,'orders','Заказы','orders.admin','shopping-cart')},async unregister(){}};export default JaseflyFrontendModule;